select case when c.country in ('JP', 'UK') then 'core' else 'other' end as country_group, c.segment, max(s.shipped_date) as latest_shipped_date, min(s.delivered_date) as first_delivered_date from shipments s join orders o on s.order_id = o.id left join customers c on o.customer_id = c.id where o.customer_id = 38 group by case when c.country in ('JP', 'UK') then 'core' else 'other' end, c.segment order by latest_shipped_date asc, country_group desc;
